// Read-only bounded printed-global token/access evidence. No analysis or edits.
// @category Porsche.V2
import ghidra.app.util.headless.HeadlessScript;
import ghidra.app.decompiler.*;
import ghidra.program.model.address.*;
import ghidra.program.model.data.*;
import ghidra.program.model.listing.*;
import ghidra.program.model.pcode.*;
import ghidra.program.model.symbol.*;
import com.google.gson.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;

public class ExportGlobalAliases194 extends HeadlessScript {
 private final Gson json=new GsonBuilder().disableHtmlEscaping().setPrettyPrinting().create();
 private final String sha="ddd748fdbe6d2030e31f9257a4e01852749460b6b58560a6b4a8559d3799ff39";
 private Map<String,Object> row(Object...p){Map<String,Object>r=new LinkedHashMap<>();for(int i=0;i<p.length;i+=2)r.put((String)p[i],p[i+1]);return r;}
 private void write(Path p,Object o)throws Exception{Files.writeString(p,json.toJson(o)+"\n",StandardCharsets.UTF_8);}
 private Object type(DataType t){return t==null?null:row("path",t.getPathName(),"name",t.getName(),"class",t.getClass().getName(),"bytes",t.getLength(),"alignment",t.getAlignment());}
 private Object storage(VariableStorage s){List<Object>v=new ArrayList<>();for(Varnode n:s.getVarnodes())v.add(row("space",n.getAddress().getAddressSpace().getName(),"address",n.getAddress().toString(),"offset",Long.toUnsignedString(n.getOffset()),"bytes",n.getSize()));return row("display",s.toString(),"bytes",s.size(),"memory",s.isMemoryStorage(),"register",s.isRegisterStorage(),"varnodes",v);}
 private Object symbol(HighSymbol s){return s==null?null:row("name",s.getName(),"namespace",s.getNamespace()==null?null:s.getNamespace().getName(true),"type",type(s.getDataType()),"bytes",s.getSize(),"storage",storage(s.getStorage()),"type_locked",s.isTypeLocked());}
 private Object node(Varnode n,int depth){if(n==null)return null;Map<String,Object>r=row("space",n.getAddress().getAddressSpace().getName(),"address",n.getAddress().toString(),"offset",Long.toUnsignedString(n.getOffset()),"bytes",n.getSize(),"constant",n.isConstant(),"input",n.isInput());HighVariable h=n.getHigh();if(h!=null){r.put("high_name",h.getName());r.put("high_type",type(h.getDataType()));r.put("high_symbol",symbol(h.getSymbol()));r.put("high_symbol_offset",h.getOffset());}PcodeOp d=n.getDef();if(d!=null){r.put("defined_at",d.getSeqnum().getTarget().toString());r.put("defined_by",d.getMnemonic());if(depth>0)r.put("producer",op(d,depth-1));}return r;}
 private Object op(PcodeOp p,int depth){if(p==null)return null;List<Object>a=new ArrayList<>();for(Varnode n:p.getInputs())a.add(node(n,depth));return row("sequence",p.getSeqnum().toString(),"pc",p.getSeqnum().getTarget().toString(),"opcode",p.getMnemonic(),"output",node(p.getOutput(),0),"inputs",a);}
 private void tokens(ClangNode n,String alias,List<Object>out){if(n instanceof ClangToken){ClangToken t=(ClangToken)n;if(alias.equals(t.getText())){Varnode v=t.getVarnode();List<Object>uses=new ArrayList<>();if(v!=null){Iterator<PcodeOp>it=v.getDescendants();while(it.hasNext())uses.add(op(it.next(),1));}out.add(row("kind",t.getClass().getSimpleName(),"text",t.getText(),"pc",t.getMinAddress()==null?null:t.getMinAddress().toString(),"varnode",node(v,2),"consumer",op(t.getPcodeOp(),1),"uses",uses));}}for(int i=0;i<n.numChildren();i++)tokens(n.Child(i),alias,out);}
 private Object instruction(Instruction ins)throws Exception{List<Object>ops=new ArrayList<>(),refs=new ArrayList<>();for(PcodeOp p:ins.getPcode())ops.add(op(p,0));for(Reference r:ins.getReferencesFrom())refs.add(row("to",r.getToAddress().toString(),"space",r.getToAddress().getAddressSpace().getName(),"kind",r.getReferenceType().toString(),"read",r.getReferenceType().isRead(),"write",r.getReferenceType().isWrite(),"operand",r.getOperandIndex()));return row("pc",ins.getAddress().toString(),"bytes",HexFormat.of().formatHex(ins.getBytes()),"assembly",ins.toString(),"references",refs,"raw_pcode",ops);}
 @Override public void run()throws Exception{
  String[]args=getScriptArgs();if(args.length!=2)throw new IllegalArgumentException("output case-json");Path out=Path.of(args[0]).toAbsolutePath().normalize();Files.createDirectories(out);JsonArray cases=JsonParser.parseString(Files.readString(Path.of(args[1]))).getAsJsonArray();if(cases.size()>12)throw new IllegalArgumentException("Pilot cap12 aliases");
  if(!currentProgram.getName().equals("Porsche.exe")||!sha.equalsIgnoreCase(currentProgram.getExecutableSHA256()))throw new IllegalStateException("Original identity mismatch");String nativePath=currentProgram.getExecutablePath();if(nativePath.startsWith("/")&&nativePath.charAt(2)==':')nativePath=nativePath.substring(1);if(!sha.equals(HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(Path.of(nativePath))))))throw new IllegalStateException("Original bytes mismatch");boolean before=currentProgram.isChanged();
  DecompInterface di=new DecompInterface();di.toggleCCode(true);di.toggleSyntaxTree(true);if(!di.openProgram(currentProgram))throw new IllegalStateException(di.getLastMessage());Map<String,DecompileResults>cache=new LinkedHashMap<>();List<Object>result=new ArrayList<>();
  try{for(JsonElement element:cases){JsonObject c=element.getAsJsonObject();String va=c.get("va").getAsString(),alias=c.get("alias").getAsString();Address target=toAddr(c.get("address").getAsString());Function f=getFunctionAt(toAddr(va));if(f==null)throw new IllegalStateException("Missing function "+va);DecompileResults d=cache.get(va);if(d==null){d=di.decompileFunction(f,60,monitor);if(!d.decompileCompleted()||d.getHighFunction()==null)throw new IllegalStateException("Decompile failed "+va+": "+d.getErrorMessage());cache.put(va,d);Files.writeString(out.resolve(va+".c"),d.getDecompiledFunction().getC().replace("\r\n","\n"),StandardCharsets.UTF_8);}
    List<Object>ts=new ArrayList<>(),original=new ArrayList<>();tokens(d.getCCodeMarkup(),alias,ts);InstructionIterator instructions=currentProgram.getListing().getInstructions(f.getBody(),true);while(instructions.hasNext()){Instruction ins=instructions.next();boolean match=false;for(Reference r:ins.getReferencesFrom())if(r.getToAddress().equals(target)){match=true;break;}if(match)original.add(instruction(ins));}
    List<Object>formal=new ArrayList<>();Iterator<HighSymbol>si=d.getHighFunction().getGlobalSymbolMap().getSymbols();while(si.hasNext()){HighSymbol s=si.next();VariableStorage st=s.getStorage();if(!st.isMemoryStorage())continue;for(Varnode v:st.getVarnodes())if(v.getAddress().getAddressSpace().equals(target.getAddressSpace())&&target.getOffset()>=v.getOffset()&&target.getOffset()<v.getOffset()+v.getSize()){formal.add(symbol(s));break;}}
    Data data=currentProgram.getListing().getDataContaining(target);Object listing=data==null?null:row("address",data.getAddress().toString(),"bytes",data.getLength(),"type",type(data.getDataType()),"offset",target.subtract(data.getAddress()));Map<String,Object>r=row("va",va,"alias",alias,"address",target.toString(),"function_min",f.getBody().getMinAddress().toString(),"function_max",f.getBody().getMaxAddress().toString(),"tokens",ts,"formal_symbols_at_address",formal,"original_references",original,"listing_data",listing);result.add(r);write(out.resolve(va+"-"+alias+".json"),r);println("ALIAS194 "+va+" "+alias+" tokens="+ts.size()+" original_refs="+original.size());
   }}finally{di.dispose();}
  boolean after=currentProgram.isChanged();if(before!=after)throw new IllegalStateException("Program mutation detected");write(out.resolve("result.json"),row("original_sha256",sha,"ghidra_version",ghidra.framework.Application.getApplicationVersion(),"language",currentProgram.getLanguageID().toString(),"compiler_spec",currentProgram.getCompilerSpec().getCompilerSpecID().toString(),"program_changed_before",before,"program_changed_after",after,"analysis",false,"read_only",true,"cases",result));
 }
}
